int far win_Events(void)
{
    struct MSG msg;
    int acted;

    acted = 0;
    if (PeekMessage(&msg, 0, 0, 0, 1)) {
        do {
            if (msg.message == 0x201 || msg.message == 0x202)
                acted = 1;
            if (msg.message == 0x100 &&
                (msg.wParam == 0x20 || msg.wParam == 0x2d))
                acted = 1;
            TranslateMessage(&msg);
            DispatchMessage(&msg);
        } while (PeekMessage(&msg, 0, 0, 0, 1));
    }
    return acted;
}
